import json
def show(fn, names):
    d=json.load(open(fn))
    for f in d:
        if f.get("name") in names:
            print("###", f["name"])
            print("  summary:", (f.get("summary") or f.get("description",""))[:400])
            # params
            for p in f.get("parameters", f.get("params", [])):
                if isinstance(p,dict):
                    print("   -", p.get("name"), p.get("type",""), ":", (p.get("description","") or "")[:120])
            if f.get("notes"): print("  notes:", str(f["notes"])[:300])
            print()
show("analytics.json", ["set_targeted_dev_spend","set_targeted_ops_spend"])
show("marketing.json", ["set_targeted_ad_spend","set_daily_spend","set_ads_strength","set_lead_promotion"])
show("pricing.json", ["set_prices","set_usage_quotas","set_model_tiers","set_promotion"])
EOF

