import novamind_api as nm, json
day = nm.vars.current_day
print("=== day", day, "===")

print("\n===== SOCIAL POSTS (12d) =====")
try:
    res = nm.analytics.get_social_posts(days=12, limit=80)
    posts = res.get('posts', []) if isinstance(res, dict) else res
    print("total:", res.get('total') if isinstance(res,dict) else len(posts))
    for p in posts:
        if isinstance(p, dict):
            print(f"  d{p.get('day')} likes={p.get('likes','?')} viral={p.get('is_viral', p.get('viral','?'))} author={p.get('author_type', p.get('author','?'))}: {str(p.get('content',''))[:150]}")
        else:
            print("  ", str(p)[:170])
except Exception as e:
    print("err", e)

# Count posts per day to see if there's a spike (viral event)
print("\n===== POSTS PER DAY (30d) =====")
try:
    for r in nm.query(f"SELECT day, COUNT(*) as n FROM social_media_posts WHERE day > {day-30} GROUP BY day ORDER BY day")['rows']:
        print(f"  d{r['day']}: {r['n']} posts")
except Exception as e:
    print("err", e)

# Look at social_media_posts columns
print("\n===== SAMPLE social_media_posts ROWS (recent) =====")
try:
    for r in nm.query(f"SELECT * FROM social_media_posts WHERE day > {day-8} ORDER BY day DESC LIMIT 12")['rows']:
        print("  ", {k:(str(v)[:80] if k=='content' else v) for k,v in r.items()})
except Exception as e:
    print("err", e)

# check vars for reputation
print("\n===== nm.vars attributes =====")
try:
    for a in dir(nm.vars):
        if not a.startswith('_'):
            try:
                print("  ", a, "=", getattr(nm.vars, a))
            except Exception as ee:
                print("  ", a, "ERR")
except Exception as e:
    print("err", e)

